// Store
import { type } from '../../shared/utility/utilityHelpers';
export const ActionTypes = {
  // LOGIN ACTIONTYPES
  DO_LOGIN: type('[Auth] Do Login'),
  DO_LOGIN_SUCCESS: type('[Auth] Do Login Success'),
  DO_LOGIN_FAIL: type('[Auth] Do Login Fail'),
  // FORGOT PASSWORD ACTIONTYPES
  DO_FORGOT_PASSWORD: type('[Auth] Do Forgot Password'),
  DO_FORGOT_PASSWORD_SUCCESS: type('[Auth] Do Forgot Password Success'),
  DO_FORGOT_PASSWORD_FAIL: type('[Auth] Do Forgot Password Fail')
}; // LOGIN ACTION

export class DoLoginAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.DO_LOGIN;
  }

}
export class DoLoginSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.DO_LOGIN_SUCCESS;
  }

}
export class DoLoginFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.DO_LOGIN_FAIL;
  }

} // FORGET ACTION

export class DoForgotPasswordAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.DO_FORGOT_PASSWORD;
  }

}
export class DoForgotPasswordSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.DO_FORGOT_PASSWORD_SUCCESS;
  }

}
export class DoForgotPasswordFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.DO_FORGOT_PASSWORD_FAIL;
  }

}
